let s8={learned:{},sessions:[],problems:[],round:0,excluded:[]};
const key8=(n,g)=>`${n} × ${g}`;
function persist8(){saveLearning8()}
function learn8(n,g){if(!Number.isInteger(n)||!Number.isInteger(g)||n<2||n>9||g<1||g>9)return;const key=key8(n,g);if(s8.excluded.includes(key))return;if(!s8.learned[key])s8.learned[key]={key,n,g,level:null,history:[]};persist8()}
function sync8(){for(const c of s5.cards){const [n,g]=c.key.split(' × ').map(Number);learn8(n,g);const item=s8.learned[c.key];if(item&&item.level===null)item.level=['바로 떠올림','아는 식으로 해결','그림을 보고 해결'].indexOf(c.route)}for(const c of s6.bank)if(c.history.length||c.imported){learn8(c.n,c.g);if(s8.learned[c.key]&&!s8.learned[c.key].history.length)s8.learned[c.key].level=c.level}for(const c of s7.cards){learn8(c.n,c.g);if(!s8.problems.some(p=>p.scene===c.scene&&p.n===c.n&&p.g===c.g&&p.item===c.item))s8.problems.push({...c})}persist8()}
function start8(){sync8();view='stage8';const pool=Object.values(s8.learned);const days=new Set(s8.sessions.map(x=>x.date));app.innerHTML=`<section class="activity"><span class="pill">8단계 · 구구단 섞어 풀기</span><h1>배운 식을 다시 꺼내 봐요</h1><p>식·그림·생활 문제를 섞어서 5문제를 풀어요. 막히면 단서로 찾아도 좋아요. 시간제한과 점수는 없어요.</p><div class="actions"><button class="primary" onclick="begin8()" ${pool.length<5?'disabled':''}>오늘의 5문제 시작</button><button onclick="range8()">배운 식 확인·추가</button></div><p>${pool.length} / 72개 식을 배운 범위로 표시했어요.${pool.length<5?' 실제로 배운 식을 5개 이상 선택하면 시작할 수 있어요.':''}</p><p class="small" id="storageNote8">학습 기록 저장을 준비하고 있어요.</p><h2>나의 복습 기록</h2>${s8.sessions.length?`<p>${days.size}일 동안 ${s8.sessions.length}번 짧게 연습했어요. 한 번의 결과로 구구단 전체를 완성했다고 판단하지 않아요.</p>${s8.sessions.slice(-8).reverse().map(x=>`<article class="review-session"><strong>${x.date} · ${x.results.length}문제 해결</strong><p>${x.results.map(r=>`${r.key}: ${labels6[r.level]}${r.improved?' · 지난번보다 적은 도움':''}`).join('<br>')}</p></article>`).join('')}`:'<p>첫 도전을 마치면 날짜와 해결 방법이 여기에 남아요.</p>'}<div class="actions"><button onclick="start6()">카드함 짧게 열기</button><button onclick="home()">전체 단계</button></div></section>`;storageNote8()}
function storageNote8(){const el=document.querySelector('#storageNote8');if(el)el.textContent=storageError8||'이 브라우저에 배운 범위·카드·날짜별 기록을 저장해요. 다른 기기나 브라우저와 자동으로 공유되지 않으며, 브라우저 데이터를 지우면 기록도 사라져요.'}
function range8(){view='stage8';app.innerHTML=`<section class="activity"><span class="pill">배운 범위</span><h1>실제로 배운 식만 표시해요</h1><p>파란 식은 ‘배운 식’, 흰 식은 ‘아직 배우지 않은 식’이에요. 식을 누르면 표시가 바뀝니다. 선택한 식만 8단계 문제에 나와요.</p><p class="small">3~7단계에서 해결한 식도 자동으로 추가돼요. 처음 사용하는 기기라면 어른과 함께 이전에 배운 식을 확인해 주세요.</p><button onclick="markBasics8()">2단·5단을 모두 배웠어요</button><div class="range-table">${Array.from({length:8},(_,i)=>i+2).map(n=>`<section><h2>${n}단</h2><div class="range-row">${Array.from({length:9},(_,i)=>i+1).map(g=>`<button class="${s8.learned[key8(n,g)]?'primary':''}" aria-pressed="${!!s8.learned[key8(n,g)]}" onclick="toggle8(${n},${g})">${n} × ${g}<small>${s8.learned[key8(n,g)]?'배운 식':'아직'}</small></button>`).join('')}</div></section>`).join('')}</div><p class="small">새로운 식은 3~6단계의 묶음 늘리기·배열·아는 식 방법으로 살펴본 뒤 추가해요.</p><button class="primary" onclick="start8()">배운 범위로 돌아가기</button></section>`}
function markBasics8(){for(const n of [2,5])for(let g=1;g<=9;g++){s8.excluded=s8.excluded.filter(k=>k!==key8(n,g));learn8(n,g)}range8()}
function toggle8(n,g){const k=key8(n,g);if(s8.learned[k]){delete s8.learned[k];s8.excluded.push(k)}else{s8.excluded=s8.excluded.filter(x=>x!==k);learn8(n,g)}persist8();range8()}
function shuffled8(list){const out=[...list];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function begin8(){const all=Object.values(s8.learned);if(all.length<5){range8();return}const pending=all.filter(c=>c.level>0||c.history.at(-1)?.wrong);const previous=new Set(s8.sessions.at(-1)?.results.map(r=>r.key)||[]);const fresh=shuffled8(all.filter(c=>!previous.has(c.key))),others=shuffled8(all);let picked=[];function add(c){if(c&&!picked.some(x=>x.key===c.key))picked.push(c)}shuffled8(pending).slice(0,2).forEach(add);[...fresh,...others].forEach(add);picked=picked.slice(0,5);const second=picked.findIndex((x,i)=>i>0&&x.n!==picked[0].n);if(second>1)[picked[1],picked[second]]=[picked[second],picked[1]];const types=shuffled8(['equation','equation','picture','life']);s8.queue=picked.map((c,i)=>({key:c.key,type:i===4?'review':types[i]}));const custom=s8.problems.filter(c=>s8.learned[key8(c.n,c.g)]);if(custom.length){const p=custom[s8.round%custom.length],at=s8.queue.findIndex(q=>q.type==='life');if(at>=0&&!s8.queue.some((q,i)=>i!==at&&q.key===key8(p.n,p.g))){s8.queue[at]={key:key8(p.n,p.g),type:'life',problem:p}}}s8.pos=0;s8.results=[];s8.round++;s8.revisit=false;init8()}
const item8=()=>s8.learned[s8.queue[s8.pos].key];
function init8(){Object.assign(s8,{hint:'',level:0,wrong:false,passed:false,msg:'먼저 혼자 떠올려 봐요. 막히면 단서를 골라요.'});render8()}
function hint8(type){s8.hint=type;s8.level=Math.max(s8.level,type==='picture'?2:1);s8.msg='한 묶음의 개수만큼 더하면 다음 답을 찾을 수 있어요.';render8()}
function diagram8(c){return `<div class="group-grid">${Array.from({length:c.g},(_,i)=>`<div class="group-box ${i===c.g-1?'new':''}"><small>${i+1}묶음</small>${Array(c.n).fill('●').join(' ')}</div>`).join('')}</div>`}
function answer8(a,b,total){const c=item8(),q=s8.queue[s8.pos],needs=q.type==='picture'||q.type==='life';if(!Number.isInteger(total)||(needs&&(!Number.isInteger(a)||!Number.isInteger(b)))){s8.msg='답 칸을 숫자로 채워 주세요.';render8();return}if(needs&&(a!==c.n||b!==c.g)){s8.wrong=true;s8.msg=a!==c.n?'첫 수는 한 묶음 안의 개수예요. 한 묶음만 살펴보고 다시 써요.':'둘째 수는 그런 묶음의 수예요. 묶음을 하나씩 짚어 보세요.';render8();return}if(total!==c.n*c.g){s8.wrong=true;s8.msg='다시 생각해 봐요. 아는 식이나 묶음 그림을 이용해도 좋아요.';render8();return}const old=c.level,improved=old!==null&&s8.level<old;s8.results.push({key:c.key,level:s8.level,wrong:s8.wrong,improved,type:q.type});c.level=s8.level;c.history.push({level:s8.level,wrong:s8.wrong});s8.passed=true;s8.msg=`${c.key} = ${c.n*c.g}. ${labels6[s8.level]}!${improved?' 지난번보다 적은 도움으로 해결했어요.':''}`;if((s8.level>0||s8.wrong)&&s8.pos<=2&&!s8.revisit){s8.queue[4]={key:c.key,type:'review'};s8.revisit=true}persist8();render8()}
function next8(){if(!s8.passed)return;s8.pos++;if(s8.pos===5){finish8();return}init8()}
function render8(){view='stage8';const c=item8(),q=s8.queue[s8.pos],needs=q.type==='picture'||q.type==='life';let prompt='';if(q.type==='picture')prompt=`<h2>그림에 맞는 식과 답을 만들어요.</h2>${diagram8(c)}`;else if(q.type==='life'){const p=q.problem;prompt=p?`<h2>내가 만든 문제</h2><p class="story-text">${escape7(story7(p))}<br>${escape7(question7(p))}</p>`:`<h2>생활 속 문제</h2><p class="story-text">의자가 한 줄에 ${c.n}개씩, ${c.g}줄 있어요.<br>의자는 모두 몇 개일까요?</p>`}else prompt=`<h2>${q.type==='review'?'다시 꺼내 보기':'식 보고 답하기'}</h2><div class="recall-face">${c.key} = ${s8.passed?c.n*c.g:'?'}</div>`;if(s8.hint==='picture'&&q.type!=='picture')prompt+=diagram8(c);if(s8.hint)prompt+=`<div class="clue-strip">${c.n} × ${c.g-1} = ${c.n*(c.g-1)}<br>한 묶음 ${c.n}개를 더해요: ${c.n*(c.g-1)} + ${c.n} = □</div>`;app.innerHTML=`<div class="topline"><span class="pill">8단계 · 오늘의 5문제</span><span>${s8.pos+1} / 5</span></div><section class="activity">${prompt}${s8.passed?`<div class="feedback good" role="status">${s8.msg}</div><button class="primary" onclick="next8()">${s8.pos===4?'오늘의 기록 보기':'다음 문제 →'}</button>`:`<form id="answerForm8">${needs?'<div class="equation-inputs"><label>몇 개씩<input id="first8" type="number" inputmode="numeric" min="1" max="9" required></label><b>×</b><label>몇 묶음<input id="second8" type="number" inputmode="numeric" min="1" max="9" required></label><b>=</b><label>모두 몇 개<input id="answer8" type="number" inputmode="numeric" min="0" max="81" required></label></div>':'<label for="answer8">답</label><div class="answer-entry"><input id="answer8" type="number" inputmode="numeric" min="0" max="81" required></div>'}<button class="primary" type="submit">답 확인</button></form><div class="actions"><button onclick="hint8('equation')">아는 식 찾기</button><button onclick="hint8('picture')">묶음 그림 보기</button></div><p class="feedback" role="status">${s8.msg}</p>`}<button onclick="start8()">복습 홈</button></section>`;const form=document.querySelector('#answerForm8');if(form)form.onsubmit=e=>{e.preventDefault();const read=id=>{const v=document.querySelector('#'+id).value;return v.trim()===''?NaN:Number(v)};answer8(needs?read('first8'):c.n,needs?read('second8'):c.g,read('answer8'))}}
function date8(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function finish8(){s8.sessions.push({date:date8(),results:s8.results.map(x=>({...x}))});persist8();const names=['혼자 떠올린 식','아는 식으로 찾은 식','그림을 보고 찾은 식'];app.innerHTML=`<section class="activity"><span class="pill">오늘의 복습 기록</span><h1>오늘은 5문제를 해결했어요.</h1><p>단서를 써서 찾은 답도 내가 해결한 답이에요.</p>${names.map((name,i)=>`<h2>${name}</h2><p>${s8.results.filter(r=>r.level===i).map(r=>r.key+(r.improved?' ★ 지난번보다 적은 도움':'')).join(', ')||'이번에는 없어요.'}</p>`).join('')}<h2>다시 살펴볼 식</h2><p>${[...new Set(s8.results.filter(r=>r.level>0||r.wrong).map(r=>r.key))].join(', ')||'다음 날 다른 배운 식과 함께 다시 만나 봐요.'}</p><p>다음 도전에는 도움이 필요했던 식을 먼저 섞어요. 여러 날의 기록에서 혼자 떠올리는 식이 늘어나는지 살펴봐요.</p><p class="small" id="storageNote8"></p><div class="actions"><button class="primary" onclick="begin8()">다른 5문제 만나기</button><button onclick="start8()">날짜별 기록 보기</button><button onclick="range8()">배운 범위 넓히기</button><button onclick="home()">전체 단계</button></div></section>`;storageNote8()}
