const previousNext3=next3;next3=function(){if(s3.passed){const d=d3();learn8(d.n,d.type==='grow'||d.type==='life'?d.g+1:d.type==='subtract'?d.g-1:d.type==='repair'?4:s3.g)}return previousNext3()};
const previousNext4=next4;next4=function(){if(s4.passed&&s4.phase==='reason'){learn8(d4().n,d4().g);learn8(d4().g,d4().n)}return previousNext4()};
const previousSave5=saveCard5;saveCard5=function(){previousSave5();learn8(d5().n,d5().g)};
const previousCommit6=commit6;commit6=function(){previousCommit6();learn8(card6().n,card6().g)};
const previousCheck7=check7;check7=function(a,b,c){previousCheck7(a,b,c);if(s7.phase==='success')sync8()};
